package com.example.gymlog2

object TipsTranslator {
    fun translateTip(tipText: String, lang: String): String {
        if (lang == "en" || lang.startsWith("en")) return tipText
        val translationsMap = when (lang) {
            "ro" -> roTranslations
            "ru" -> ruTranslations
            "uk" -> ukTranslations
            "fr" -> frTranslations
            "de" -> deTranslations
            "es" -> esTranslations
            "it" -> itTranslations
            "tr" -> trTranslations
            "pt" -> ptTranslations
            "pl" -> plTranslations
            else -> emptyMap()
        }
        return translationsMap[tipText] ?: tipText
    }

